(function (window,$) { "use strict";const Portfolio = window.Portfolio = window.Portfolio || {};Portfolio.config = {email: "umairshaikh7738@gmail.com",phone: "+917738635355",whatsapp: "917738635355",linkedin: "https://www.linkedin.com/in/umair-shaikh-9b2054254",previousPortfolio: "https://umairportfolio-1.netlify.app/",github: "",codepen: ""};Portfolio.utils = {escapeHtml(value) {return String(value || "").replace(/[&<>'"]/g, function (char) {
        return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#039;", '"': "&quot;" })[char];
      });
    },

    slugify(value) {
      return String(value || "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
    },

    prefersReducedMotion() {
      return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    },

    refreshIcons() {
      if (window.lucide) {
        window.lucide.createIcons({ attrs: { "stroke-width": 1.7 } });
      }
    },

    splitCharacters(selector) {
      document.querySelectorAll(selector).forEach(function (element) {
        if (element.dataset.splitReady) return;
        const label = element.textContent.trim();
        element.setAttribute("aria-label", label);
        element.innerHTML = Array.from(label).map(function (char) {
          const output = char === " " ? "&nbsp;" : Portfolio.utils.escapeHtml(char);
          return '<span class="char" aria-hidden="true">' + output + "</span>";
        }).join("");
        element.dataset.splitReady = "true";
      });
    },

    splitWords(selector) {
      document.querySelectorAll(selector).forEach(function (element) {
        if (element.dataset.splitReady) return;
        const label = element.textContent.trim();
        element.setAttribute("aria-label", label);
        element.innerHTML = label.split(/\s+/).map(function (word) {
          return '<span class="word" aria-hidden="true"><span class="word-inner">' + Portfolio.utils.escapeHtml(word) + "</span></span>";
        }).join(" ");
        element.dataset.splitReady = "true";
      });
    },

    getQuery(name) {
      return new URLSearchParams(window.location.search).get(name);
    }
  };

  Portfolio.loadComponents = function () {
    const elements = Array.from(document.querySelectorAll("[data-component]"));
    return Promise.all(elements.map(function (element) {
      const component = element.dataset.component;
      return new Promise(function (resolve) {
        $(element).load("components/" + component + ".html", function (_response, status) {
          if (status === "error") {
            element.innerHTML = "";
          }
          resolve();
        });
      });
    }));
  };

  Portfolio.hydrateGlobalContent = function () {
    document.querySelectorAll("[data-current-year]").forEach(function (node) {
      node.textContent = new Date().getFullYear();
    });

    const service = Portfolio.utils.getQuery("service");
    const projectType = document.querySelector("#projectType");
    if (service && projectType) {
      const readable = service.replace(/-/g, " ");
      Array.from(projectType.options).some(function (option) {
        if (option.textContent.toLowerCase().includes(readable.toLowerCase())) {
          option.selected = true;
          return true;
        }
        return false;
      });
    }

    document.querySelectorAll("[data-profile]").forEach(function (node) {
      const url = Portfolio.config[node.dataset.profile];
      if (!url) {
        node.hidden = true;
      } else {
        node.href = url;
      }
    });
  };
})(window, window.jQuery);

(function (window, $) {
  "use strict";

  const Portfolio = window.Portfolio = window.Portfolio || {};

  Portfolio.Navigation = {
    init() {
      this.setActiveLink();
      this.initTheme();
      this.initHeader();
      this.initScrollActions();
      this.initAnchorLinks();
      this.initCursor();
      this.initMagnetic();
    },

    setActiveLink() {
      const page = document.body.dataset.page || "home";
      document.querySelectorAll('[data-nav="' + page + '"]').forEach(function (link) {
        link.classList.add("active");
        link.setAttribute("aria-current", "page");
      });
    },

    initTheme() {
      const root = document.documentElement;
      const stored = localStorage.getItem("portfolio-theme");
      const initial = stored || "dark";
      root.dataset.theme = initial;

      document.querySelectorAll(".theme-toggle").forEach(function (button) {
        button.setAttribute("aria-pressed", String(initial === "light"));
        button.addEventListener("click", function () {
          const next = root.dataset.theme === "light" ? "dark" : "light";
          root.dataset.theme = next;
          localStorage.setItem("portfolio-theme", next);
          button.setAttribute("aria-pressed", String(next === "light"));
        });
      });
    },

    initHeader() {
      const header = document.querySelector("[data-site-header]");
      if (!header) return;
      let previous = window.scrollY;
      const update = function () {
        const current = window.scrollY;
        header.classList.toggle("is-scrolled", current > 18);
        header.classList.toggle("is-hidden", current > previous && current > 180);
        previous = Math.max(0, current);
      };
      window.addEventListener("scroll", update, { passive: true });
      update();
    },

    initScrollActions() {
      const buttons = document.querySelectorAll("[data-back-to-top], [data-back-top-inline]");
      const floating = document.querySelector("[data-back-to-top]");
      const progress = floating ? floating.querySelector("circle.progress") : null;
      const circumference = 125.66;

      buttons.forEach(function (button) {
        button.addEventListener("click", function () {
          if (window.portfolioLenis) {
            window.portfolioLenis.scrollTo(0, { duration: 1.2 });
          } else {
            window.scrollTo({ top: 0, behavior: "smooth" });
          }
        });
      });

      const update = function () {
        const total = document.documentElement.scrollHeight - window.innerHeight;
        const ratio = total > 0 ? window.scrollY / total : 0;
        if (floating) floating.classList.toggle("visible", window.scrollY > 500);
        if (progress) progress.style.strokeDashoffset = String(circumference - ratio * circumference);
      };
      window.addEventListener("scroll", update, { passive: true });
      update();
    },

    initAnchorLinks() {
      $(document).on("click", 'a[href^="#"]', function (event) {
        const id = this.getAttribute("href");
        if (!id || id === "#") return;
        const target = document.querySelector(id);
        if (!target) return;
        event.preventDefault();
        if (window.portfolioLenis) {
          window.portfolioLenis.scrollTo(target, { offset: -90, duration: 1.1 });
        } else {
          target.scrollIntoView({ behavior: "smooth" });
        }
      });
    },

    initCursor() {
      if (window.matchMedia("(hover: none), (pointer: coarse)").matches || Portfolio.utils.prefersReducedMotion()) return;

      const dot = document.createElement("div");
      const ring = document.createElement("div");
      dot.className = "cursor-dot";
      ring.className = "cursor-ring";
      document.body.append(dot, ring);

      let x = 0, y = 0, ringX = 0, ringY = 0;
      document.addEventListener("mousemove", function (event) {
        x = event.clientX;
        y = event.clientY;
        dot.style.opacity = "1";
        ring.style.opacity = "1";
      });

      const render = function () {
        ringX += (x - ringX) * 0.16;
        ringY += (y - ringY) * 0.16;
        dot.style.transform = "translate3d(" + (x - 3) + "px," + (y - 3) + "px,0)";
        ring.style.transform = "translate3d(" + (ringX - 19) + "px," + (ringY - 19) + "px,0)";
        requestAnimationFrame(render);
      };
      render();

      $(document).on("mouseenter", "a, button, input, textarea, select, .project-card", function () { ring.classList.add("is-active"); });
      $(document).on("mouseleave", "a, button, input, textarea, select, .project-card", function () { ring.classList.remove("is-active"); });
    },

    initMagnetic() {
      if (window.matchMedia("(hover: none), (pointer: coarse)").matches || Portfolio.utils.prefersReducedMotion()) return;
      document.querySelectorAll(".magnetic").forEach(function (element) {
        element.addEventListener("mousemove", function (event) {
          const rect = element.getBoundingClientRect();
          const x = event.clientX - rect.left - rect.width / 2;
          const y = event.clientY - rect.top - rect.height / 2;
          if (window.gsap) window.gsap.to(element, { x: x * .16, y: y * .16, duration: .35, ease: "power2.out" });
        });
        element.addEventListener("mouseleave", function () {
          if (window.gsap) window.gsap.to(element, { x: 0, y: 0, duration: .65, ease: "elastic.out(1,.35)" });
        });
      });
    }
  };
})(window, window.jQuery);

(function (window) {
  "use strict";

  const Portfolio = window.Portfolio = window.Portfolio || {};

  Portfolio.Loader = {
    play() {
      const loader = document.querySelector(".page-loader");
      if (!loader) {
        document.body.classList.remove("loading");
        return Promise.resolve();
      }

      if (Portfolio.utils.prefersReducedMotion() || !window.gsap) {
        loader.remove();
        document.body.classList.remove("loading");
        return Promise.resolve();
      }

      const firstVisit = !sessionStorage.getItem("portfolio-loaded");
      const duration = firstVisit ? 1.15 : .4;
      const count = { value: 0 };
      const percent = loader.querySelector("[data-loader-percent]");

      return new Promise(function (resolve) {
        const timeline = window.gsap.timeline({
          onComplete: function () {
            sessionStorage.setItem("portfolio-loaded", "true");
            loader.remove();
            document.body.classList.remove("loading");
            resolve();
          }
        });
        timeline
          .to(count, { value: 100, duration: duration, ease: "power2.inOut", onUpdate: function () { percent.textContent = Math.round(count.value) + "%"; } })
          .to(".loader-progress span", { width: "100%", duration: duration, ease: "power2.inOut" }, 0)
          .to(".loader-orbit", { rotation: 75, scale: 1.07, duration: duration, ease: "power2.inOut" }, 0)
          .to(".loader-copy", { y: -16, opacity: 0, duration: .32, ease: "power2.in" })
          .to(loader, { yPercent: -100, duration: .72, ease: "power4.inOut" }, "-=.1");
      });
    }
  };
})(window);

